import{_ as s,l as o,o as a,c as l,v as t,p as c,x as r,d as n,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"PREEMPT_RT","description":"","frontmatter":{"title":"PREEMPT_RT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/preempt-rt.md","filePath":"cs/preempt-rt.md","lastUpdated":1789023840000}'),d={name:"cs/preempt-rt.md"};function T(_,e,R,P,h,m){const i=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="preempt-rt" tabindex="-1">PREEMPT_RT <a class="header-anchor" href="#preempt-rt" aria-label="Permalink to &quot;PREEMPT_RT&quot;">​</a></h1><div class="epigraph"><p>PREEMPT_RT 把大多数内核自旋锁换成可睡眠的 rtmutex，中断线程化，使优先级高的任务能在有界时间内抢到 CPU。</p><footer>—— 据 Linux PREEMPT_RT 文档；Rostedt 对实时抢占的论述；McKusick 对内核抢占的背景</footer></div><p><a href="/cs/sched-deadline">DEADLINE</a> 假定内核别关抢占太久。<a href="/cs/kernel-preempt">内核抢占</a> 主干有程度。缺口是 <strong>RT 补丁主线化的机制</strong>：锁、IRQ 线程、延迟来源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通内核：持 spinlock 关抢占，软中断可拖延用户 RT。PREEMPT_RT：<code>raw_spinlock</code> 才真关；多数锁可被抢。IRQ：默认线程化，按优先级跑。缺口：仍有不可抢占段（关中断、硬件）；优先级继承防 <a href="/cs/priority-inversion">优先级反转</a>。本课不把每把锁的转换表列出。</p><p><span class="marginnote">cyclictest 测的就是这些段的尾巴。对象是延迟上界的工程近似，不是形式证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置 <code>PREEMPT_RT</code>。自旋改睡眠 → 可调度。对照 <a href="/cs/napi">NAPI</a>：收包可在线程上下文，延迟与吞吐折中。对照 <a href="/cs/kpti-os">KPTI</a>：陷入税仍在，RT 更敏感。对照 DPDK：旁路不靠内核抢占。</p>',8)),(a(),c(E,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20THR%5B%22IRQ%20%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20THR%20--%3E%20PI%5B%22rtmutex%20%E4%BC%98%E5%85%88%E7%BA%A7%E7%BB%A7%E6%89%BF%22%5D%0A%20%20RT%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20PRE%5B%22%E6%8A%A2%E5%8D%A0%E5%86%85%E6%A0%B8%E7%BA%BF%E7%A8%8B%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RT 内核把「内核是一个大临界区」拆开，使 SCHED_FIFO/DEADLINE 的延迟从毫秒级可降到数十微秒级（视硬件）。吞吐与调试性下降。不要写成保证书。与 <a href="/cs/dma-coherence">dma</a>：完成 IRQ 仍可能是 raw 路径。</p><p>驱动质量决定上界：一个关中断的驱动毁整机 RT。</p><p>实现上：raw_spinlock 仍关抢占，驱动若误用会毁延迟上界。中断线程的优先级要高于用户 RT 才有意义。打印与 ATA 复位仍是著名长段。 读法上只引用<a href="/cs/sched-deadline">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>PREEMPT_RT</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 xenomai 双内核。不保证云虚拟机的 RT 数字。下一课如何量延迟：cyclictest。</p><p>版本字段会变，课序钉的是机制对象「PREEMPT_RT」，不是某一主线内核的结构体名。 后课默认：内核可配置为深度抢占。用 cyclictest 看延迟分布，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PREEMPT_RT：可抢占锁 + 中断线程化 + PI。</li><li>仍有不可抢占硬件段。</li><li>延迟测量是下一课。</li><li>出处：PREEMPT_RT；Rostedt；Linux RT 文档。</li></ul>',11))])}const B=s(d,[["render",T]]);export{u as __pageData,B as default};
